    Note note; Board board; EditText linear,titleInput,searchInput; ScrollView boardScroll; FrameLayout searchResults,sideDrawerOverlay; View undoSnackbar; Dialog blockDialog; boolean isLinear=false, drawer=false, calendarMode=true,calendarCollapsed=false; int current=0, screen=0, editorReturnScreen=0, searchReturnScreen=0; float edgeDownX,edgeDownY; String pendingSearch="", activeTagFilter=""; Calendar selectedDate=Calendar.getInstance(); ArrayDeque<String> undo=new ArrayDeque<>(); ArrayList<TimeEntry> timeline=new ArrayList<>(); Handler saveHandler=new Handler(); Runnable pendingDiskSave;
    int dp(float n){return (int)(getResources().getDisplayMetrics().density*n+.5f);} 
    @Override public void onCreate(Bundle b){super.onCreate(b); getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);load();if(!notes.isEmpty())note=notes.get(0);current=0;buildHome();}
    @Override public boolean dispatchTouchEvent(android.view.MotionEvent event){int action=event.getActionMasked();if(action==MotionEvent.ACTION_DOWN){edgeDownX=event.getX();edgeDownY=event.getY();if(undoSnackbar!=null&&!touchInside(event,undoSnackbar))dismissUndoSnackbar();}else if(action==MotionEvent.ACTION_UP){float dx=event.getX()-edgeDownX,dy=event.getY()-edgeDownY;if(edgeDownX<=dp(24)&&dx>=dp(72)&&dx>Math.abs(dy)*1.25f){if(sideDrawerOverlay!=null)closeDrawer();else handleBack();return true;}}return super.dispatchTouchEvent(event);}
    boolean touchInside(MotionEvent event,View view){int[] xy=new int[2];view.getLocationOnScreen(xy);float x=event.getRawX(),y=event.getRawY();return x>=xy[0]&&x<=xy[0]+view.getWidth()&&y>=xy[1]&&y<=xy[1]+view.getHeight();}
    void dismissUndoSnackbar(){if(undoSnackbar!=null){View old=undoSnackbar;undoSnackbar=null;if(old.getParent() instanceof ViewGroup)((ViewGroup)old.getParent()).removeView(old);}}
    void showUndoSnackbar(String message,Runnable undoAction){dismissUndoSnackbar();FrameLayout host=findViewById(android.R.id.content);LinearLayout bar=row();bar.setPadding(dp(18),0,dp(10),0);bar.setBackground(shape(0xFF3B3B3B,12));bar.setElevation(dp(6));TextView label=text(message,14,Color.WHITE,false);bar.addView(label,new LinearLayout.LayoutParams(0,dp(52),1));TextView undoText=text("撤销",14,0xFFFF5A4F,true);undoText.setGravity(Gravity.CENTER);bar.addView(undoText,new LinearLayout.LayoutParams(dp(58),dp(52)));undoSnackbar=bar;bar.setOnClickListener(v->dismissUndoSnackbar());undoText.setOnClickListener(v->{dismissUndoSnackbar();undoAction.run();});FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(-1,dp(52),Gravity.BOTTOM);lp.setMargins(dp(16),0,dp(16),dp(18));host.addView(bar,lp);}
    @Override public void onBackPressed(){handleBack();}
