    void handleBack(){if(screen==4){if(editorReturnScreen==3){editorReturnScreen=0;buildSearch(pendingSearch);}else buildHome();return;}if(screen==3){if(searchReturnScreen==4)buildEditor();else if(searchReturnScreen==2)buildTimeline();else buildHome();return;}if(screen==2){buildHome();return;}super.onBackPressed();}
    GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
