    void bottomNav(int selected){LinearLayout nav=row();nav.setGravity(Gravity.CENTER);nav.setBackgroundColor(Color.WHITE);nav.setPadding(dp(12),dp(4),dp(12),dp(6));root.addView(nav,new LinearLayout.LayoutParams(-1,dp(62)));nav.setElevation(dp(4));String[] names={"首页","统计"};String[] icons={"home","stats"};for(int i=0;i<2;i++){final int page=i;LinearLayout item=new LinearLayout(this);item.setOrientation(LinearLayout.VERTICAL);item.setGravity(Gravity.CENTER);IconGlyph icon=new IconGlyph(icons[i],selected==i?ink:muted);item.addView(icon,new LinearLayout.LayoutParams(dp(23),dp(23)));TextView label=text(names[i],11,selected==i?ink:muted,selected==i);label.setGravity(Gravity.CENTER);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(20));lp.topMargin=dp(2);item.addView(label,lp);item.setOnClickListener(v->{if(page==0){screen=0;buildHome();}else{screen=2;buildTimeline();}});nav.addView(item,new LinearLayout.LayoutParams(0,-1,1));}}
    String noteContent(Note n){String content=n.text==null?"":n.text;if(!n.blocks.isEmpty()){String blocks=n.blocksText();if(!blocks.isEmpty())content=content.isEmpty()?blocks:content+"\n"+blocks;}return content;}
    boolean contains(String source,String query){return source!=null&&source.toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT));}
    boolean noteMatchesQuery(Note n,String query){if(query==null||query.isEmpty()||contains(n.title+"\n"+noteContent(n),query))return true;for(String tag:n.tags)if(contains(tag,query))return true;return false;}
    String preview(Note n){String value=noteContent(n).replace('\n',' ').trim();if(value.isEmpty())return "还没有正文";return value.length()>110?value.substring(0,110)+"…":value;}
    String searchPreview(Note n,String query){String value=noteContent(n).replace('\n',' ').trim();if(query==null||query.isEmpty()||value.isEmpty())return preview(n);int found=value.toLowerCase(Locale.ROOT).indexOf(query.toLowerCase(Locale.ROOT));if(found<0)return preview(n);int start=Math.max(0,found-38),end=Math.min(value.length(),found+query.length()+62);return (start>0?"…":"")+value.substring(start,end)+(end<value.length()?"…":"");}
    SpannableString highlight(String source,String query){SpannableString out=new SpannableString(source);if(query==null||query.isEmpty())return out;String lower=source.toLowerCase(Locale.ROOT),term=query.toLowerCase(Locale.ROOT);int at=0;while((at=lower.indexOf(term,at))>=0){out.setSpan(new BackgroundColorSpan(0xFFFFE48A),at,at+term.length(),0);out.setSpan(new ForegroundColorSpan(ink),at,at+term.length(),0);at+=term.length();}return out;}
    void buildHome(){screen=0;root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);setContentView(root);LinearLayout header=row();header.setPadding(dp(22),dp(10),dp(18),dp(8));root.addView(header,new LinearLayout.LayoutParams(-1,dp(58)));TextView title=text("首页",26,ink,true);header.addView(title,new LinearLayout.LayoutParams(0,-1,1));FrameLayout search=iconButton("搜索",()->openSearch(""));header.addView(search,new LinearLayout.LayoutParams(dp(44),dp(44)));
        FrameLayout area=new FrameLayout(this);root.addView(area,new LinearLayout.LayoutParams(-1,0,1));ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);area.addView(scroll,new FrameLayout.LayoutParams(-1,-1));LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(18),dp(8),dp(18),dp(110));scroll.addView(list);ArrayList<Note> ordered=new ArrayList<>(notes);ordered.sort((a,b)->Long.compare(b.updatedAt,a.updatedAt));if(ordered.isEmpty()){emptyHome(list,"还没有笔记","点右下角加号，开始记录片段。");}else for(Note item:ordered)addPreviewCard(list,item,"");
        FrameLayout fab=iconButton("新建笔记",()->createNote());fab.setBackground(shape(ink,40));IconGlyph plus=new IconGlyph("plus",Color.WHITE);fab.addView(plus,new FrameLayout.LayoutParams(dp(26),dp(26),Gravity.CENTER));FrameLayout.LayoutParams fp=new FrameLayout.LayoutParams(dp(56),dp(56),Gravity.RIGHT|Gravity.BOTTOM);fp.rightMargin=dp(18);fp.bottomMargin=dp(18);area.addView(fab,fp);bottomNav(0);}
    void emptyHome(LinearLayout parent,String title,String subtitle){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER);TextView t=text(title,20,ink,true);t.setGravity(Gravity.CENTER);box.addView(t);TextView s=text(subtitle,14,muted,false);s.setGravity(Gravity.CENTER);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(40));box.addView(s,sp);parent.addView(box,new LinearLayout.LayoutParams(-1,dp(300)));}
    void addPreviewCard(LinearLayout list,Note item,String query){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(18),dp(16),dp(18),dp(16));card.setBackground(shape(Color.WHITE,18));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(12);list.addView(card,cp);if(!item.title.trim().isEmpty()){TextView heading=text(item.title,18,ink,true);if(!query.isEmpty())heading.setText(highlight(item.title,query));card.addView(heading,new LinearLayout.LayoutParams(-1,-2));}String snippetValue=searchPreview(item,query);TextView snippet=text(snippetValue,14,ink,false);snippet.setGravity(Gravity.TOP);snippet.setMaxLines(3);snippet.setEllipsize(android.text.TextUtils.TruncateAt.END);if(!query.isEmpty())snippet.setText(highlight(snippetValue,query));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);if(!item.title.trim().isEmpty())sp.topMargin=dp(8);card.addView(snippet,sp);TextView meta=text(dateLabel(item.updatedAt),12,0xFFB0B0B0,false);LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(-1,dp(22));mp.topMargin=dp(10);card.addView(meta,mp);card.setOnClickListener(v->openNote(item,query));}
