    void createNote(){editorReturnScreen=0;note=new Note();notes.add(0,note);current=0;isLinear=false;pendingSearch="";persist();buildEditor();}
    void openNote(Note target,String query){editorReturnScreen=screen;current=notes.indexOf(target);if(current<0)current=0;note=target;pendingSearch=query==null?"":query;boolean blockHit=false;for(Block b:target.blocks)if(contains(b.text,pendingSearch)){blockHit=true;break;}isLinear=target.blocks.isEmpty()||(!pendingSearch.isEmpty()&&contains(target.text,pendingSearch)&&!blockHit);buildEditor();}
    void openSearch(String query){searchReturnScreen=screen;buildSearch(query);}
    void buildSearch(String query){screen=3;root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);setContentView(root);LinearLayout header=row();header.setPadding(dp(16),dp(8),dp(18),dp(8));root.addView(header,new LinearLayout.LayoutParams(-1,dp(58)));FrameLayout back=iconButton("返回",this::handleBack);header.addView(back,new LinearLayout.LayoutParams(dp(42),dp(42)));searchInput=new EditText(this);searchInput.setSingleLine(true);searchInput.setTextSize(16);searchInput.setTextColor(ink);searchInput.setHintTextColor(0xFFB0B0B0);searchInput.setHint("搜索笔记和标签");searchInput.setPadding(dp(14),0,dp(14),0);searchInput.setBackground(shape(Color.WHITE,22));searchInput.setText(query);LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(0,dp(44),1);ep.leftMargin=dp(10);header.addView(searchInput,ep);TextView clear=text("×",22,muted,false);clear.setGravity(Gravity.CENTER);header.addView(clear,new LinearLayout.LayoutParams(dp(38),dp(42)));clear.setOnClickListener(v->searchInput.setText(""));searchResults=new FrameLayout(this);root.addView(searchResults,new LinearLayout.LayoutParams(-1,0,1));bottomNav(0);searchInput.addTextChangedListener(watch(v->{activeTagFilter="";updateSearchResults(v);}));updateSearchResults(query);searchInput.requestFocus();searchInput.postDelayed(()->((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(searchInput,InputMethodManager.SHOW_IMPLICIT),180);}
    void updateSearchResults(String query){if(searchResults==null)return;searchResults.removeAllViews();ScrollView scroll=new ScrollView(this);searchResults.addView(scroll);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(18),dp(8),dp(18),dp(24));scroll.addView(list);boolean any=false;ArrayList<String> matchingLabels=new ArrayList<>();for(String label:labels){boolean hit=query==null||query.isEmpty()||contains(label,query);if(!hit)for(Note n:notes)if(noteMatchesQuery(n,query)&&n.tags.contains(label)){hit=true;break;}if(hit&&(activeTagFilter.isEmpty()||activeTagFilter.equals(label)))matchingLabels.add(label);}if(!matchingLabels.isEmpty()){TextView heading=text("标签",16,ink,true);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,dp(36));list.addView(heading,hp);for(String label:matchingLabels){TextView tag=text("标签  ·  "+label+"    ›",14,ink,false);if(query!=null&&!query.isEmpty())tag.setText(highlight("标签  ·  "+label+"    ›",query));tag.setPadding(dp(12),0,dp(12),0);tag.setBackground(shape(Color.WHITE,14));LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(-1,dp(46));tp.bottomMargin=dp(8);list.addView(tag,tp);tag.setOnClickListener(v->{activeTagFilter=label;updateSearchResults(query);});}any=true;}TextView notesHead=text("笔记",16,ink,true);LinearLayout.LayoutParams nh=new LinearLayout.LayoutParams(-1,dp(42));nh.topMargin=dp(4);list.addView(notesHead,nh);ArrayList<Note> ordered=new ArrayList<>(notes);ordered.sort((a,b)->Long.compare(b.updatedAt,a.updatedAt));int count=0;for(Note n:ordered){boolean tagMatch=activeTagFilter.isEmpty()||n.tags.contains(activeTagFilter);if(tagMatch&&noteMatchesQuery(n,query)){addPreviewCard(list,n,query==null?"":query);count++;}}if(count==0&&!any)emptyHome(list,"没有找到相关笔记","试试更短的关键词。");}
