        if(content!=null)panel.addView(content,new LinearLayout.LayoutParams(-1,-2));LinearLayout actions=row();actions.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(48));ap.topMargin=dp(16);panel.addView(actions,ap);
