        dialog.setContentView(panel);Window window=dialog.getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams lp=window.getAttributes();lp.dimAmount=.28f;window.setAttributes(lp);window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(32),dp(440)),WindowManager.LayoutParams.WRAP_CONTENT);}dialog.show();if(window!=null)window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(32),dp(440)),WindowManager.LayoutParams.WRAP_CONTENT);
