    void editTitle(){EditText input=dialogInput("未命名",note.title,1);styledPanel("编辑标题",null,input,"取消",null,"完成",()->{note.title=input.getText().toString().trim();note.updatedAt=System.currentTimeMillis();persist();build();});}
    void titleEditor(){titleInput=new EditText(this);EditText e=titleInput;e.setSingleLine(true);e.setTextSize(26);e.setTypeface(null,1);e.setTextColor(ink);e.setHintTextColor(170);e.setHint("未命名");e.setPadding(0,dp(16),0,dp(8));e.setBackgroundColor(Color.TRANSPARENT);e.setText(note.title);if(!pendingSearch.isEmpty())highlightEditor(e,pendingSearch);e.addTextChangedListener(watch(v->{note.title=v;note.updatedAt=System.currentTimeMillis();persist();}));body.addView(e,new LinearLayout.LayoutParams(-1,dp(58)));}
    interface StringChange{void change(String s);} TextWatcher watch(StringChange c){return new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){c.change(s.toString());}public void afterTextChanged(Editable e){}};}
