    void renderContent(){content.removeAllViews();if(isLinear){linear=new EditText(this);linear.setGravity(Gravity.TOP|Gravity.START);linear.setTextSize(16);linear.setTextColor(ink);linear.setHintTextColor(170);linear.setHint("把想起的内容写下来……");linear.setPadding(dp(16),dp(16),dp(16),dp(16));linear.setBackground(shape(Color.WHITE,18));linear.setText(note.text);if(!pendingSearch.isEmpty())highlightEditor(linear,pendingSearch);linear.addTextChangedListener(watch(v->{note.text=v;note.updatedAt=System.currentTimeMillis();persist();}));content.addView(linear,new FrameLayout.LayoutParams(-1,-1));}else{boardScroll=new ScrollView(this);boardScroll.setFillViewport(true);board=new Board();boardScroll.addView(board,new ScrollView.LayoutParams(-1,-2));content.addView(boardScroll,new FrameLayout.LayoutParams(-1,-1));if(!pendingSearch.isEmpty())highlightMatchingBlocks(pendingSearch);}}
    void highlightEditor(EditText editor,String query){String all=editor.getText().toString();int pos=all.toLowerCase(Locale.ROOT).indexOf(query.toLowerCase(Locale.ROOT));if(pos>=0){SpannableString span=new SpannableString(all);span.setSpan(new BackgroundColorSpan(0xFFFFE48A),pos,pos+query.length(),0);editor.setText(span);editor.setSelection(pos);editor.post(()->editor.bringPointIntoView(pos));}}
    void highlightMatchingBlocks(String query){for(Block b:note.blocks)if(contains(b.text,query)){boardScroll.post(()->boardScroll.smoothScrollTo(0,Math.max(0,(int)(b.y*board.cell)-dp(100))));break;}}
    void editBlock(int idx){editBlock(idx,0,nextY());}
    void editBlock(int idx,int startX,int startY){if(blockDialog!=null&&blockDialog.isShowing())return;final boolean existing=idx>=0;final Note owner=note;final Block old=existing?note.blocks.get(idx):new Block();if(!existing){old.x=startX;old.y=startY;old.order=nextBlockOrder();}saveUndo();EditText input=dialogInput("写下刚刚想起的内容…",old.text,4);Dialog dialog=new Dialog(this);blockDialog=dialog;LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(22),dp(20),dp(22),dp(18));panel.setBackground(shape(Color.WHITE,24));LinearLayout header=row();TextView heading=text(!existing?"记录片段":"编辑片段",20,ink,true);header.addView(heading,new LinearLayout.LayoutParams(0,dp(42),1));if(existing){FrameLayout split=new FrameLayout(this);split.setContentDescription("拆分片段");split.addView(new IconGlyph("split",ink),new FrameLayout.LayoutParams(dp(24),dp(24),Gravity.CENTER));header.addView(split,new LinearLayout.LayoutParams(dp(42),dp(42)));split.setOnClickListener(v->{int cursor=Math.max(0,Math.min(input.getSelectionStart(),input.length()));String value=input.getText().toString();if(cursor<=0||cursor>=value.length()){toast("请把光标放在片段中间再拆分");return;}String left=value.substring(0,cursor),right=value.substring(cursor);styledConfirm("拆分片段","确定将光标前后内容分成两个方块片段吗？","取消",null,"确定",()->{dialog.dismiss();saveUndo();old.text=left;Block second=new Block();second.text=right;second.x=old.x;second.y=old.y+Math.max(1,old.h)+1;for(Block candidate:note.blocks)if(candidate.order>old.order)candidate.order++;second.order=old.order+1;note.blocks.add(Math.min(note.blocks.indexOf(old)+1,note.blocks.size()),second);normalizeBlockOrder();note.updatedAt=System.currentTimeMillis();persist();renderContent();});});TextView delete=text("删除",14,0xFFE44332,true);delete.setGravity(Gravity.CENTER);header.addView(delete,new LinearLayout.LayoutParams(dp(48),dp(42)));delete.setOnClickListener(v->{dialog.dismiss();deleteBlock(old);});}FrameLayout done=new FrameLayout(this);done.setContentDescription("保存");done.addView(new IconGlyph("check",ink),new FrameLayout.LayoutParams(dp(24),dp(24),Gravity.CENTER));header.addView(done,new LinearLayout.LayoutParams(dp(42),dp(42)));panel.addView(header,new LinearLayout.LayoutParams(-1,dp(42)));input.setGravity(Gravity.TOP|Gravity.START);input.setMinLines(4);input.setPadding(dp(14),dp(16),dp(14),dp(16));input.setBackground(shape(0xFFF7F7F7,16));LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(-1,0,1);ip.topMargin=dp(12);panel.addView(input,ip);Runnable flush=()->{old.text=input.getText().toString();old.sized=false;if(!owner.blocks.contains(old)&&!old.text.isEmpty())owner.blocks.add(old);owner.updatedAt=System.currentTimeMillis();persist();if(pendingDiskSave!=null)saveHandler.removeCallbacks(pendingDiskSave);pendingDiskSave=()->{getSharedPreferences("suiyi",0).edit().commit();pendingDiskSave=null;};saveHandler.postDelayed(pendingDiskSave,400);};input.addTextChangedListener(watch(value->{flush.run();}));done.setOnClickListener(v->{flush.run();if(pendingDiskSave!=null){saveHandler.removeCallbacks(pendingDiskSave);pendingDiskSave=null;}getSharedPreferences("suiyi",0).edit().commit();dialog.dismiss();});dialog.setOnDismissListener(v->{if(blockDialog==dialog)blockDialog=null;if(note==owner&&screen==4)renderContent();});dialog.setContentView(panel);Window window=dialog.getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}dialog.show();if(window!=null){window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(32),dp(440)),(int)(getResources().getDisplayMetrics().heightPixels*.72f));WindowManager.LayoutParams params=window.getAttributes();params.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;params.y=(int)(getResources().getDisplayMetrics().heightPixels*.26f);window.setAttributes(params);}input.requestFocus();input.postDelayed(()->((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(input,InputMethodManager.SHOW_IMPLICIT),160);}
    void deleteBlock(Block target){Note owner=note;int index=owner.blocks.indexOf(target);if(index<0)return;owner.blocks.remove(index);owner.updatedAt=System.currentTimeMillis();persist();if(note==owner&&screen==4)renderContent();showUndoSnackbar("已删除笔记",()->{owner.blocks.add(Math.min(index,owner.blocks.size()),target);owner.updatedAt=System.currentTimeMillis();persist();if(note==owner&&screen==4)renderContent();});}
    int nextY(){int y=0;for(Block b:note.blocks)y=Math.max(y,b.y+b.h);return y;}
    void normalizeBlockOrder(){ArrayList<Block> sorted=new ArrayList<>(note.blocks);sorted.sort((a,b)->Integer.compare(a.order,b.order));for(int i=0;i<sorted.size();i++)sorted.get(i).order=i;}
    int nextBlockOrder(){int next=0;for(Block b:note.blocks)next=Math.max(next,b.order+1);return next;}
    void saveUndo(){try{undo.push(note.json().toString());if(undo.size()>20)undo.removeLast();}catch(Exception ignored){}}
    void undo(){if(undo.isEmpty()){toast("没有可撤销的操作");return;}try{note=new Note(new JSONObject(undo.pop()));notes.set(current,note);persist();build();}catch(Exception ignored){}}
    void copyAll(){String s=isLinear?linear.getText().toString():note.blocksText();if(!isLinear)note.text=s;((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("碎忆",s));toast("已复制全文");}
    void showMenu(){String[] items={"复制全文",note.favorite?"取消收藏":"收藏笔记","转换为普通笔记","删除笔记"};Runnable[] actions={this::copyAll,()->{note.favorite=!note.favorite;persist();toast(note.favorite?"已收藏":"已取消收藏");},()->{note.text=note.blocksText();isLinear=true;build();},this::trashNote};Dialog dialog=new Dialog(this);LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(20),dp(18),dp(20),dp(18));panel.setBackground(shape(Color.WHITE,20));LinearLayout header=row();TextView title=text("笔记操作",19,ink,true);header.addView(title,new LinearLayout.LayoutParams(0,dp(38),1));TextView close=text("×",24,muted,false);close.setGravity(Gravity.CENTER);header.addView(close,new LinearLayout.LayoutParams(dp(38),dp(38)));close.setOnClickListener(v->dialog.dismiss());panel.addView(header);GridLayout grid=new GridLayout(this);grid.setColumnCount(2);grid.setPadding(0,dp(8),0,0);for(int i=0;i<items.length;i++){final int index=i;TextView option=text(items[i],15,index==3?0xFFE44332:ink,true);option.setGravity(Gravity.CENTER);option.setBackground(shape(index==3?0xFFFFF1F0:0xFFF3F3F3,10));GridLayout.LayoutParams lp=new GridLayout.LayoutParams(GridLayout.spec(i/2),GridLayout.spec(i%2,1f));lp.width=0;lp.height=dp(76);lp.setMargins(dp(4),dp(4),dp(4),dp(4));grid.addView(option,lp);option.setOnClickListener(v->{dialog.dismiss();actions[index].run();});}panel.addView(grid,new LinearLayout.LayoutParams(-1,dp(172)));dialog.setContentView(panel);Window window=dialog.getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(40),dp(400)),WindowManager.LayoutParams.WRAP_CONTENT);}dialog.show();if(window!=null)window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(40),dp(400)),WindowManager.LayoutParams.WRAP_CONTENT);}
    void trashNote(){Note removed=note;int oldIndex=notes.indexOf(removed);notes.remove(removed);trash.add(0,removed);if(notes.isEmpty()){note=new Note();current=0;}else{current=Math.min(current,notes.size()-1);note=notes.get(current);}persist();buildHome();showUndoSnackbar("已删除笔记",()->{trash.remove(removed);notes.add(Math.min(oldIndex,notes.size()),removed);current=notes.indexOf(removed);note=removed;persist();buildHome();});}
