        void resizeTo(float x,float y){Block b=resizing;int right=resizeX+resizeW,bottom=resizeY+resizeH;int nx=(resizeCorner%2==0)?Math.max(0,Math.min(right-1,Math.round((x-offsetX)/cell))):resizeX;int ny=(resizeCorner<2)?Math.max(0,Math.min(bottom-1,Math.round((y-offsetY)/cell))):resizeY;int nw=(resizeCorner%2==0)?right-nx:Math.max(1,Math.round((x-offsetX)/cell)-nx);int nh=(resizeCorner<2)?bottom-ny:Math.max(1,Math.round((y-offsetY)/cell)-ny);int columns=Math.max(4,(int)((getWidth()-dp(20))/cell));if(nx+nw>columns)return;android.text.TextPaint tp=new android.text.TextPaint(3);tp.setTextSize(dp(14));android.text.StaticLayout layout=android.text.StaticLayout.Builder.obtain(b.text,0,b.text.length(),tp,Math.max(1,(int)(nw*cell-dp(22)))).setIncludePad(false).build();nh=Math.max(nh,(int)Math.ceil((layout.getHeight()+dp(18))/cell));for(Block other:note.blocks)if(other!=b&&nx<other.x+other.w&&nx+nw>other.x&&ny<other.y+other.h&&ny+nh>other.y)return;b.x=nx;b.y=ny;b.w=nw;b.h=nh;b.sized=true;b.sizedText=b.text;requestLayout();invalidate();}
        boolean canPlace(Block candidate,int x,int y){int columns=Math.max(4,(int)((getWidth()-dp(20))/cell)),rows=Math.max(24,getHeight()/(int)cell);if(x<0||y<0||x+candidate.w>columns||y+candidate.h>rows)return false;for(Block other:note.blocks)if(other!=candidate&&x<other.x+other.w&&x+candidate.w>other.x&&y<other.y+other.h&&y+candidate.h>other.y)return false;return true;}
        ArrayList<Block> orderedBlocks(){ArrayList<Block> ordered=new ArrayList<>(note.blocks);ordered.sort((a,b)->Integer.compare(a.order,b.order));return ordered;}
        Block findOther(float x,float y,Block source){for(int i=note.blocks.size()-1;i>=0;i--){Block b=note.blocks.get(i);if(b==source)continue;float l=offsetX+b.x*cell,t=offsetY+b.y*cell,r=l+b.w*cell,bot=t+b.h*cell;if(x>=l&&x<=r&&y>=t&&y<=bot)return b;}return null;}
        void updateInsertion(float y){ArrayList<Block> ordered=orderedBlocks();ordered.remove(moving);insertionIndex=0;insertionY=offsetY-dp(3);for(Block b:ordered){float mid=offsetY+b.y*cell+b.h*cell/2f;if(y>mid){insertionIndex++;insertionY=offsetY+(b.y+b.h)*cell+dp(3);}else{insertionY=offsetY+b.y*cell-dp(3);break;}}}
        Block find(float x,float y){for(int i=note.blocks.size()-1;i>=0;i--){Block b=note.blocks.get(i);float l=offsetX+b.x*cell,t=offsetY+b.y*cell,r=l+b.w*cell,bot=t+b.h*cell;if(x>=l&&x<=r&&y>=t&&y<=bot)return b;}return null;}
        boolean overlap(Block a,Block b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;}
